<div class="d-flex justify-content-between align-items-center mb-4"><h1>📤 Historial de Salidas</h1><a href="index.php?controller=salida&action=registrar" class="btn btn-warning">➕ Nueva Salida</a></div><div class="card"><div class="card-body table-responsive"><?php if(empty($salidas)): ?><div class="alert alert-info text-center">No hay salidas registradas.</div><?php else: ?><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Fecha</th><th>Producto</th><th>Cantidad</th><th>Razón</th><?php if(($_SESSION['user_role']??'')==='admin'): ?><th>Acciones</th><?php endif; ?></tr></thead><tbody><?php foreach($salidas as $s): ?><tr><td><?= date('d/m/Y H:i',strtotime($s['Fecha_Salida'])) ?></td><td><?= htmlspecialchars($s['ProductoNombre'],ENT_QUOTES,'UTF-8') ?></td><td><span class="badge bg-warning text-dark"><?= (int)$s['Cantidad'] ?></span></td><td><?= htmlspecialchars($s['Razon']??'',ENT_QUOTES,'UTF-8') ?></td><?php if(($_SESSION['user_role']??'')==='admin'): ?><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary edit-salida" data-bs-toggle="modal" data-bs-target="#editSalida" data-id="<?= (int)$s['ID_Salida'] ?>" data-producto="<?= (int)$s['ID_Producto'] ?>" data-cantidad="<?= (int)$s['Cantidad'] ?>" data-razon="<?= htmlspecialchars($s['Razon']??'',ENT_QUOTES,'UTF-8') ?>">Actualizar</button><form class="d-inline" method="post" action="index.php?controller=salida&action=eliminar" onsubmit="return confirm('¿Eliminar salida y restituir stock?')"><input type="hidden" name="id" value="<?= (int)$s['ID_Salida'] ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></div>
<?php if(($_SESSION['user_role']??'')==='admin'): ?><div class="modal fade" id="editSalida" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" method="post" action="index.php?controller=salida&action=actualizar"><div class="modal-header"><h5 class="modal-title">Actualizar salida</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="ID_Salida" id="salId"><div class="mb-3"><label class="form-label">Producto</label><select class="form-select" name="ID_Producto" id="salProd" required><?php foreach($productos as $p): ?><option value="<?= (int)$p['ID_Producto'] ?>"><?= htmlspecialchars($p['Nombre'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Cantidad</label><input class="form-control" type="number" min="1" name="Cantidad" id="salCant" required></div><div class="mb-3"><label class="form-label">Razón</label><input class="form-control" name="Razon" id="salRazon" maxlength="50" required></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar cambios</button></div></form></div></div><script>document.querySelectorAll('.edit-salida').forEach(b=>b.addEventListener('click',function(){document.getElementById("salId").value=this.dataset.id;document.getElementById("salProd").value=this.dataset.producto;document.getElementById("salCant").value=this.dataset.cantidad;document.getElementById("salRazon").value=this.dataset.razon;}));</script><?php endif; ?>
